def find_status(answer, modes):
    if len(modes) == num_opt: return 'Absent'
    if len(modes) == 1:
        if modes[0] == answer: return 'Consistent Correct'
        else: return 'Consistent Wrong'
    if answer in modes: return 'Conflicting Correct'
